package kvhttp

import java.util.concurrent.ConcurrentHashMap

private val KEY_REGEX = Regex("[A-Za-z0-9_-]{1,64}")

/** Thread-safe in-memory key-value store. */
class Store {
    private val data = ConcurrentHashMap<String, ByteArray>()

    /** Stores [value] under [key]; returns true if the key was newly created. */
    fun put(key: String, value: ByteArray): Boolean = data.put(key, value) == null

    fun get(key: String): ByteArray? = data[key]

    fun delete(key: String): Boolean = data.remove(key) != null

    fun keys(): List<String> = data.keys.sorted()
}

/** Routes requests to the store. Pure request-to-response logic with no I/O. */
class App(private val store: Store = Store()) {

    fun handle(req: Request): Response {
        val path = req.path
        return when {
            path == "/health" ->
                if (req.method != "GET") methodNotAllowed("GET")
                else Response(Status.OK, "ok".toByteArray(), mapOf("Content-Type" to "text/plain; charset=utf-8"))

            path == "/kv" ->
                if (req.method != "GET") methodNotAllowed("GET")
                else Response(Status.OK, keysJson().toByteArray(), mapOf("Content-Type" to "application/json"))

            path.startsWith("/kv/") -> {
                val key = path.removePrefix("/kv/")
                if (KEY_REGEX.matches(key)) handleKey(req, key) else Response(Status.BAD_REQUEST)
            }

            else -> Response(Status.NOT_FOUND)
        }
    }

    private fun handleKey(req: Request, key: String): Response = when (req.method) {
        "GET" -> store.get(key)
            ?.let { Response(Status.OK, it, mapOf("Content-Type" to "application/octet-stream")) }
            ?: Response(Status.NOT_FOUND)

        "PUT" -> Response(if (store.put(key, req.body)) Status.CREATED else Status.OK)

        "DELETE" -> Response(if (store.delete(key)) Status.NO_CONTENT else Status.NOT_FOUND)

        else -> methodNotAllowed("GET, PUT, DELETE")
    }

    // Keys are restricted to [A-Za-z0-9_-], so they never need JSON escaping.
    private fun keysJson(): String = store.keys().joinToString(",", "[", "]") { "\"$it\"" }

    private fun methodNotAllowed(allow: String) = Response(Status.METHOD_NOT_ALLOWED, headers = mapOf("Allow" to allow))
}

package kvhttp

/** The subset of HTTP status codes this server produces. */
enum class Status(val code: Int, val phrase: String) {
    OK(200, "OK"),
    CREATED(201, "Created"),
    NO_CONTENT(204, "No Content"),
    BAD_REQUEST(400, "Bad Request"),
    NOT_FOUND(404, "Not Found"),
    METHOD_NOT_ALLOWED(405, "Method Not Allowed"),
    CONTENT_TOO_LARGE(413, "Content Too Large"),
    REQUEST_HEADER_FIELDS_TOO_LARGE(431, "Request Header Fields Too Large"),
    NOT_IMPLEMENTED(501, "Not Implemented"),
}

/** Signals a request that must be answered with [status] instead of being routed. */
class HttpException(val status: Status) : Exception(status.phrase)

class Request(
    val method: String,
    val path: String,
    /** Header names are lower-cased; a repeated header keeps its last value. */
    val headers: Map<String, String>,
    val body: ByteArray = EMPTY_BODY,
)

class Response(
    val status: Status,
    val body: ByteArray = EMPTY_BODY,
    val headers: Map<String, String> = emptyMap(),
) {
    /** Serializes the response; the connection is always closed after it. */
    fun encode(): ByteArray {
        val head = buildString {
            append("HTTP/1.1 ").append(status.code).append(' ').append(status.phrase).append("\r\n")
            val all = headers + mapOf("Content-Length" to body.size.toString(), "Connection" to "close")
            for ((name, value) in all) append(name).append(": ").append(value).append("\r\n")
            append("\r\n")
        }
        return head.toByteArray(Charsets.ISO_8859_1) + body
    }
}

internal val EMPTY_BODY = ByteArray(0)

package kvhttp

import kotlin.system.exitProcess

fun main(args: Array<String>) {
    val port = args.singleOrNull()
        ?.takeIf { arg -> arg.isNotEmpty() && arg.all { it in '0'..'9' } }
        ?.toIntOrNull()
        ?.takeIf { it in 1..65535 }
    if (port == null) {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    Server(App()).serve("127.0.0.1", port)
}

package kvhttp

import java.io.EOFException
import java.io.InputStream

const val MAX_VALUE_BYTES = 1024 * 1024
const val MAX_HEADER_BYTES = 64 * 1024

private val HEAD_END = "\r\n\r\n".toByteArray()
private val CRLF = "\r\n".toByteArray()

/** Thrown when a delimiter is not found within the allowed number of bytes. */
class LimitOverrunException : Exception("delimiter not found within limit")

/**
 * Buffered reader for HTTP/1.1 requests. Throws [EOFException] when the peer
 * closes the connection before a complete request has arrived.
 */
class RequestReader(private val input: InputStream, private val limit: Int = MAX_HEADER_BYTES) {
    private var buf = ByteArray(8192)
    private var start = 0
    private var end = 0

    fun readRequest(): Request {
        val head = try {
            readUntil(HEAD_END)
        } catch (_: LimitOverrunException) {
            throw HttpException(Status.REQUEST_HEADER_FIELDS_TOO_LARGE)
        }
        val lines = String(head, 0, head.size - HEAD_END.size, Charsets.ISO_8859_1).split("\r\n")

        val parts = lines.first().split(" ")
        if (parts.size != 3 || !parts[2].startsWith("HTTP/")) throw HttpException(Status.BAD_REQUEST)
        val (method, target) = parts

        val headers = HashMap<String, String>()
        for (line in lines.drop(1)) {
            val colon = line.indexOf(':')
            if (colon <= 0) throw HttpException(Status.BAD_REQUEST)
            val name = line.substring(0, colon)
            if (name != name.trim()) throw HttpException(Status.BAD_REQUEST)
            headers[name.lowercase()] = line.substring(colon + 1).trim()
        }

        val path = target.substringBefore('?')
        val transferEncoding = headers["transfer-encoding"]
        val body = if (transferEncoding != null) {
            if (!transferEncoding.equals("chunked", ignoreCase = true)) throw HttpException(Status.NOT_IMPLEMENTED)
            readChunkedBody()
        } else {
            readFixedBody(headers["content-length"])
        }
        return Request(method, path, headers, body)
    }

    private fun readFixedBody(rawLength: String?): ByteArray {
        if (rawLength == null) return EMPTY_BODY
        if (rawLength.isEmpty() || !rawLength.all { it in '0'..'9' }) throw HttpException(Status.BAD_REQUEST)
        val length = rawLength.trimStart('0').ifEmpty { "0" }
        // Compare lengths first so that absurdly long digit strings cannot overflow.
        if (length.length > 7 || length.toInt() > MAX_VALUE_BYTES) throw HttpException(Status.CONTENT_TOO_LARGE)
        return readExactly(length.toInt())
    }

    private fun readChunkedBody(): ByteArray {
        val chunks = mutableListOf<ByteArray>()
        var total = 0
        while (true) {
            val sizeLine = String(readLine(), Charsets.ISO_8859_1).substringBefore(';').trim()
            val size = sizeLine.toIntOrNull(16)?.takeIf { it >= 0 } ?: throw HttpException(Status.BAD_REQUEST)
            if (size == 0) {
                // Discard trailers up to the terminating blank line.
                while (!readLine().contentEquals(CRLF)) Unit
                return concat(chunks, total)
            }
            total += size
            if (total > MAX_VALUE_BYTES) throw HttpException(Status.CONTENT_TOO_LARGE)
            chunks += readExactly(size)
            if (!readExactly(CRLF.size).contentEquals(CRLF)) throw HttpException(Status.BAD_REQUEST)
        }
    }

    private fun readLine(): ByteArray = try {
        readUntil(CRLF)
    } catch (_: LimitOverrunException) {
        throw HttpException(Status.BAD_REQUEST)
    }

    /** Reads up to and including [delimiter], which must start within [limit] bytes. */
    private fun readUntil(delimiter: ByteArray): ByteArray {
        var scanned = 0 // bytes after `start` already known not to begin the delimiter
        while (true) {
            val found = indexOf(delimiter, start + scanned)
            if (found >= 0) {
                if (found - start > limit) throw LimitOverrunException()
                val stop = found + delimiter.size
                return buf.copyOfRange(start, stop).also { start = stop }
            }
            if (end - start > limit) throw LimitOverrunException()
            scanned = maxOf(0, end - start - delimiter.size + 1)
            if (!fill()) throw EOFException()
        }
    }

    private fun readExactly(n: Int): ByteArray {
        val out = ByteArray(n)
        val buffered = minOf(n, end - start)
        buf.copyInto(out, 0, start, start + buffered)
        start += buffered
        var filled = buffered
        while (filled < n) {
            val read = input.read(out, filled, n - filled)
            if (read < 0) throw EOFException()
            filled += read
        }
        return out
    }

    private fun indexOf(needle: ByteArray, from: Int): Int {
        outer@ for (i in from..end - needle.size) {
            for (j in needle.indices) if (buf[i + j] != needle[j]) continue@outer
            return i
        }
        return -1
    }

    /** Compacts or grows the buffer and reads more data; returns false at end of stream. */
    private fun fill(): Boolean {
        if (start > 0) {
            buf.copyInto(buf, 0, start, end)
            end -= start
            start = 0
        }
        if (end == buf.size) buf = buf.copyOf(buf.size * 2)
        val read = input.read(buf, end, buf.size - end)
        if (read < 0) return false
        end += read
        return true
    }

    private fun concat(chunks: List<ByteArray>, total: Int): ByteArray {
        val out = ByteArray(total)
        var offset = 0
        for (chunk in chunks) {
            chunk.copyInto(out, offset)
            offset += chunk.size
        }
        return out
    }
}

package kvhttp

import java.io.EOFException
import java.io.IOException
import java.io.InputStream
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.SocketTimeoutException
import java.util.concurrent.Executors
import java.util.logging.Level
import java.util.logging.Logger
import kotlin.time.Duration
import kotlin.time.Duration.Companion.seconds
import kotlin.time.TimeSource

private val log: Logger = Logger.getLogger("kvhttp")

/**
 * Blocking HTTP/1.1 server running each connection on a virtual thread.
 * Serves exactly one request per connection, then closes it.
 */
class Server(
    private val app: App,
    private val readTimeout: Duration = 30.seconds,
) {
    fun serve(host: String, port: Int) {
        ServerSocket().use { listener ->
            listener.reuseAddress = true
            listener.bind(InetSocketAddress(InetAddress.getByName(host), port), BACKLOG)
            Executors.newVirtualThreadPerTaskExecutor().use { executor ->
                while (true) {
                    val socket = listener.accept()
                    executor.execute { handleConnection(socket) }
                }
            }
        }
    }

    private fun handleConnection(socket: Socket) {
        socket.use {
            try {
                val response = try {
                    app.handle(RequestReader(DeadlineInputStream(socket, readTimeout)).readRequest())
                } catch (e: HttpException) {
                    Response(e.status)
                }
                socket.getOutputStream().apply {
                    write(response.encode())
                    flush()
                }
                socket.shutdownOutput()
            } catch (_: EOFException) {
                // Client went away mid-request; nothing useful to send.
            } catch (_: SocketTimeoutException) {
                // Client stalled past the read deadline.
            } catch (_: IOException) {
                // Connection reset or similar transport failure.
            } catch (e: Exception) {
                log.log(Level.WARNING, "unhandled error while serving request", e)
            }
        }
    }

    private companion object {
        const val BACKLOG = 1024
    }
}

/** Enforces a total deadline across all reads of a socket, not just per read call. */
private class DeadlineInputStream(private val socket: Socket, timeout: Duration) : InputStream() {
    private val deadline = TimeSource.Monotonic.markNow() + timeout
    private val input = socket.getInputStream()

    override fun read(): Int {
        armTimeout()
        return input.read()
    }

    override fun read(b: ByteArray, off: Int, len: Int): Int {
        armTimeout()
        return input.read(b, off, len)
    }

    private fun armTimeout() {
        val remaining = -deadline.elapsedNow()
        if (!remaining.isPositive()) throw SocketTimeoutException("read deadline exceeded")
        socket.soTimeout = remaining.inWholeMilliseconds.coerceIn(1, Int.MAX_VALUE.toLong()).toInt()
    }
}
